const $=id=>document.getElementById(id);
let token='',page=1,snapshot=null,epoch=0;
const node=(tag,text='')=>{const e=document.createElement(tag);e.textContent=text;return e};
const controls=node('div');controls.className='toolbar';controls.hidden=true;
const search=node('input');search.type='search';search.maxLength=180;search.placeholder='Acteur, action ou ressource';search.setAttribute('aria-label','Recherche journal');
const size=node('select');size.setAttribute('aria-label','Éléments par page');for(const n of [10,25,50,100])size.append(new Option(String(n),String(n)));
const action=node('select');action.setAttribute('aria-label','Décision');for(const [v,t] of [['','Toutes les actions'],['AUTORISE','Autorisé'],['REFUSE','Refusé']])action.append(new Option(t,v));
const prev=node('button','Précédent'),next=node('button','Suivant'),refresh=node('button','Actualiser');controls.append(search,action,size,prev,next,refresh);$('notice').after(controls);
const posture=node('section');posture.hidden=true;controls.after(posture);
function clear(){epoch++;token='';snapshot=null;page=1;controls.hidden=true;posture.hidden=true;posture.replaceChildren();$('rows').replaceChildren();$('notice').textContent='Affichage effacé.'}
async function load(){const current=++epoch;const q=new URLSearchParams({page,size:size.value,q:search.value,action:action.value});if(snapshot!==null)q.set('snapshot',snapshot);try{const r=await fetch('/api/admin/audit?'+q,{headers:{Authorization:'Bearer '+token}}),d=await r.json();if(current!==epoch||!token)return;if(!r.ok)throw Error(d.error);snapshot=d.snapshot;$('rows').replaceChildren();for(const x of d.items){const row=node('tr');for(const v of [x.created_at,x.actor,x.action,x.resource])row.append(node('td',v));$('rows').append(row)}controls.hidden=false;posture.hidden=false;posture.replaceChildren(node('h2','Contrôle des habilitations'),node('p','Comptes actifs, activation et MFA par rôle ; aucune donnée secrète.'));const list=node('ul');for(const x of d.roles)list.append(node('li',`${x.role} : ${x.active} actifs · ${x.activated} activés · ${x.mfa} MFA${x.mfa_required?' (obligatoire)':''}`));posture.append(list);$('notice').textContent=`Page ${page} · ${d.total} événements correspondants`;prev.disabled=page===1;next.disabled=page*Number(size.value)>=d.total}catch(e){if(current===epoch){$('rows').replaceChildren();posture.replaceChildren();posture.hidden=true;$('notice').textContent=e.message}}}
$('form').onsubmit=e=>{e.preventDefault();clear();token=$('token').value;$('token').value='';load()};
$('clear').onclick=clear;
search.oninput=()=>{page=1;if(token)load()};action.onchange=size.onchange=()=>{page=1;if(token)load()};prev.onclick=()=>{if(token&&page>1){page--;load()}};next.onclick=()=>{if(token&&!next.disabled){page++;load()}};refresh.onclick=()=>{if(token){snapshot=null;page=1;load()}};
